// Current language
let currentLang = 'en';

// Get translation
function t(key) {
  return TRANSLATIONS[currentLang][key] || TRANSLATIONS['en'][key] || key;
}

// Set language
function setLanguage(lang) {
  if (TRANSLATIONS[lang]) {
    currentLang = lang;
    chrome.storage.local.set({ language: lang });
    updateAllTexts();
  }
}

// Load saved language
function loadSavedLanguage() {
  chrome.storage.local.get(['language'], (result) => {
    if (result.language && TRANSLATIONS[result.language]) {
      currentLang = result.language;
      updateAllTexts();
    }
  });
}

// Update all UI texts
function updateAllTexts() {
  // Update elements with data-i18n attribute
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.getAttribute('data-i18n');
    if (el.tagName === 'INPUT') {
      el.placeholder = t(key);
    } else if (el.children.length === 0) {
      // Only set textContent when there are no child elements to preserve
      el.textContent = t(key);
    } else {
      // Has child elements — update only the first text node to avoid wiping children
      const textNode = Array.from(el.childNodes).find(n => n.nodeType === Node.TEXT_NODE);
      if (textNode) {
        textNode.textContent = t(key);
      }
    }
  });
  
  // Update specific elements
  const headerTitle = document.querySelector('.header h3');
  if (headerTitle) headerTitle.textContent = t('appTitle');
  
  // Update language selector display
  const langDisplay = document.getElementById('currentLang');
  if (langDisplay) {
    const langNames = { en: 'EN', hi: 'हिं', ta: 'த', kn: 'ಕ', te: 'తె' };
    langDisplay.textContent = langNames[currentLang] || 'EN';
  }
}
